create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'user' check (role in ('user','admin')),created_at timestamptz not null default now());
create table if not exists public.announcements (id uuid primary key default gen_random_uuid(),title text not null,body text not null,published boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.result_archive (id uuid primary key default gen_random_uuid(),title text not null,result_date date not null,numbers text not null,is_demo boolean not null default true,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.announcements enable row level security;alter table public.result_archive enable row level security;
create policy "Users read own profile" on public.profiles for select to authenticated using (auth.uid() = id);
create policy "Users update own name" on public.profiles for update to authenticated using (auth.uid() = id) with check (auth.uid() = id);
create policy "Public read published announcements" on public.announcements for select using (published = true);
create policy "Public read demo results" on public.result_archive for select using (is_demo = true);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, full_name) values (new.id, new.raw_user_meta_data ->> 'full_name'); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
